#include <IRremote.hpp>

const int IR_RECEIVE_PIN = 4;

void setup() {
  Serial.begin(115200);

  IrReceiver.begin(IR_RECEIVE_PIN, DISABLE_LED_FEEDBACK);

  Serial.println("Готов! Нажми кнопку пульта.");
}

void loop() {
  if (IrReceiver.decode()) {
    Serial.println("Получен сигнал!");

    Serial.print("Протокол: ");
    Serial.println(
      getProtocolString(IrReceiver.decodedIRData.protocol)
    );

    Serial.print("Адрес: 0x");
    Serial.println(
      IrReceiver.decodedIRData.address, HEX
    );

    Serial.print("Команда: 0x");
    Serial.println(
      IrReceiver.decodedIRData.command, HEX
    );

    IrReceiver.resume();
  }
}
